function getNetomiTranslation(key, lang) {
  if (netomiTranslations[lang] && netomiTranslations[lang][key]) {
    return netomiTranslations[lang][key];
  }
  if (netomiTranslations.en && netomiTranslations.en[key]) {
    return netomiTranslations.en[key];
  }
  return null;
}

function applyNetomiTranslations(lang) {
  console.log(`🔥 Applying netomi translations for: ${lang}`);
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.netomi.') || key.startsWith('review.common.'))) {
      const translation = getNetomiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  console.log(`✅ Applied ${count} netomi translations`);
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyNetomiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyNetomiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyNetomiTranslations(currentLang);
}

console.log('✅ netomi i18n loaded');
